arguments.content:
package config

import (
	"fmt"
)

type Config struct {
	Host string
	Port int
}

func (c *Config) Addr() string {
	return fmt.Sprintf("%s:%d", c.Host, c.Port)
}

func DefaultConfig() *Config {
	return &Config{
		Host:   "localhost",
		Port:   8080,
	}
}

